// Bun : serveur HTTP minimal
const server = Bun.serve({
  port: 3000,
  fetch(req) {
    return new Response('Hello, World!', {
      headers: { 'Content-Type': 'text/plain; charset=utf-8' },
    });
  },
});

console.log(`Serveur Bun sur http://localhost:${server.port}`);
